/**
 * Background / parallax review grid. For each of the 3 levels:
 *   - source scene PNG (the single 16:9 image generated by backgrounds.js)
 *   - the 3 sliced layer PNGs (bg / mid / ground)
 *   - the full in-game canvas with the player stationed in that level
 *
 * Produces a 3-row × 5-col grid so you can confirm at a glance that every
 * level's backdrop is populated, the three parallax bands read as sky /
 * buildings / ground, and the composed scene runs in the engine.
 *
 * Usage:
 *   node tools/theme/capture-backgrounds.js            # base
 *   node tools/theme/capture-backgrounds.js neon_samurai
 *
 * Output:
 *   test-screenshots/backgrounds-<theme|base>-grid.png
 *   test-screenshots/backgrounds-<theme|base>-level<N>-ingame.png
 */
const { chromium } = require('playwright-core');
const http = require('http');
const fs = require('fs');
const path = require('path');
const sharp = require('sharp');

const ROOT = path.join(__dirname, '..', '..');
const PORT = 8784;
const MIME = { '.html':'text/html','.js':'text/javascript','.png':'image/png','.mp3':'audio/mp3','.wav':'audio/wav','.ogg':'audio/ogg','.json':'application/json' };

const server = http.createServer((req, res) => {
  const url = req.url.split('?')[0];
  const p = path.join(ROOT, url === '/' ? 'index.html' : url);
  fs.readFile(p, (err, data) => {
    if (err) { res.writeHead(404); res.end(); return; }
    res.writeHead(200, { 'Content-Type': MIME[path.extname(p)] || 'application/octet-stream' });
    res.end(data);
  });
});

// Asset paths depend on whether we're reviewing a theme or the base game.
function layerPath(themeId, level, kind) {
  if (themeId) return path.join(ROOT, 'src', 'themes', themeId, 'bg', `level${level}-${kind}.png`);
  const prefix = ['city', 'warehouse', 'rooftop'][level - 1];
  return path.join(ROOT, 'src', `${prefix}-${kind}.png`);
}
function scenePath(themeId, level) {
  // Scene PNG only exists for themes (authored layer per base level is direct).
  if (!themeId) return null;
  return path.join(ROOT, 'src', 'themes', themeId, 'bg', `level${level}-scene.png`);
}

async function main() {
  const themeId = process.argv[2] || '';
  const label = themeId || 'base';
  const outDir = path.join(ROOT, 'test-screenshots');
  fs.mkdirSync(outDir, { recursive: true });

  await new Promise(r => server.listen(PORT, r));
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 960, height: 540 } });

  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

  const url = `http://localhost:${PORT}/index.html${themeId ? '?theme=' + themeId : ''}`;
  console.log(`[capture-backgrounds] ${url}`);
  await page.goto(url);
  await page.waitForFunction(() => window.game && window.game.spritesReady, { timeout: 20000 });
  await page.locator('body').click({ force: true }).catch(() => {});
  async function tap(k) { await page.keyboard.down(k); await page.waitForTimeout(110); await page.keyboard.up(k); await page.waitForTimeout(110); }
  await tap('Enter'); await tap('Enter');
  await page.waitForFunction(() => window.game.scene === 'playing', { timeout: 10000 }).catch(() => {});
  await page.waitForTimeout(300);
  await page.evaluate(() => {
    const g = window.game;
    g.__frozenUpdate = g.update; g.update = () => {};
    if (g.player) { g.player.__frozenUpdate = g.player.update; g.player.update = () => {}; }
  });

  const ingameShots = [];
  for (let level = 1; level <= 3; level++) {
    await page.evaluate((lvl) => {
      const g = window.game;
      // Engine levels are 0-indexed internally.
      if (typeof g.loadLevel === 'function') g.loadLevel(lvl - 1);
      else g.currentLevel = lvl - 1;
      g.enemies = []; g.boss = null; g.items = []; g.destructibles = [];
      if (g.camera) g.camera.x = 0;
      if (g.player) { g.player.x = 100; g.player.y = 170; }
      if (typeof g.render === 'function') g.render();
    }, level);
    const canvasRect = await page.evaluate(() => {
      const c = document.getElementById('gameCanvas');
      const cb = c.getBoundingClientRect();
      return { x: Math.round(cb.left), y: Math.round(cb.top), width: Math.round(cb.width), height: Math.round(cb.height) };
    });
    const out = path.join(outDir, `backgrounds-${label}-level${level}-ingame.png`);
    await page.screenshot({ path: out, clip: canvasRect });
    ingameShots.push(out);
    console.log(`  level ${level} in-game → ${path.relative(ROOT, out)}`);
  }

  // Grid: rows = level, cols = [scene, bg, mid, ground, in-game]
  const cellW = 240, cellH = 160, labelW = 80, headerH = 24, gap = 6;
  const COLS = ['scene', 'bg', 'mid', 'ground', 'in-game'];
  const gridW = labelW + COLS.length * (cellW + gap) + gap;
  const gridH = headerH + 3 * (cellH + gap) + gap;
  const composites = [];

  for (let c = 0; c < COLS.length; c++) {
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${cellW}" height="${headerH}"><rect width="100%" height="100%" fill="#1e1e24"/><text x="6" y="16" font-family="monospace" font-size="13" fill="#ffcc66">${COLS[c]}</text></svg>`;
    composites.push({ input: await sharp(Buffer.from(svg)).png().toBuffer(), top: 5, left: labelW + c * (cellW + gap) });
  }

  for (let level = 1; level <= 3; level++) {
    const rowY = headerH + 5 + (level - 1) * (cellH + gap);
    const labelSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="${labelW}" height="${cellH}"><rect width="100%" height="100%" fill="#1e1e24"/><text x="6" y="${Math.floor(cellH / 2)}" font-family="monospace" font-size="12" fill="#ffcc66">Level ${level}</text></svg>`;
    composites.push({ input: await sharp(Buffer.from(labelSvg)).png().toBuffer(), top: rowY, left: 5 });

    const cellSources = [
      scenePath(themeId, level),
      layerPath(themeId, level, 'bg'),
      layerPath(themeId, level, 'mid'),
      layerPath(themeId, level, 'ground'),
      ingameShots[level - 1],
    ];
    for (let c = 0; c < COLS.length; c++) {
      const src = cellSources[c];
      let buf;
      if (src && fs.existsSync(src)) {
        buf = await sharp(src).resize(cellW, cellH, { fit: 'contain', background: '#0a0a10' }).png().toBuffer();
      } else {
        // Empty placeholder.
        const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${cellW}" height="${cellH}"><rect width="100%" height="100%" fill="#222"/><text x="8" y="${cellH/2}" font-family="monospace" font-size="11" fill="#666">(not emitted for base)</text></svg>`;
        buf = await sharp(Buffer.from(svg)).png().toBuffer();
      }
      composites.push({ input: buf, top: rowY, left: labelW + c * (cellW + gap) });
    }
  }

  const gridPath = path.join(outDir, `backgrounds-${label}-grid.png`);
  await sharp({ create: { width: gridW, height: gridH, channels: 4, background: '#12121a' } })
    .composite(composites).png().toFile(gridPath);
  console.log(`\n[capture-backgrounds] grid → ${path.relative(ROOT, gridPath)}`);

  if (errors.length) {
    console.log('[capture-backgrounds] page errors:');
    errors.forEach(e => console.log('  ' + e));
  }
  await browser.close();
  server.close();
}

main().catch(e => { console.error('[capture-backgrounds] CRASHED:', e.message); process.exit(1); });
